import XCTest
import CryptoKit
#if canImport(Security)
import Security
#endif
@testable import QAudionEngine

/// The call-key priority of docs/security/CALL_KEY_PRIORITY.md: the order of the pre-shared keys, which is the
/// order of the caller's advert and the order of the list in Key management.
///
/// The conformance table is `Crypto/Resources/call-key-priority-cases.tsv`, a byte-for-byte copy of the file the
/// Android tests run too (generated by `docs/security/gen_key_priority_cases.py`). Every row is run through
/// `CallKeyPriority`, the one type the real list uses, twice: operation by operation on the type itself, and the way
/// the app reaches it, with the list rebuilt from the keys the vault holds after every step.
///
/// Keychain-free: the store runs over an in-memory backing, because the CI simulator refuses real Keychain access.
final class CallKeyPriorityTests: XCTestCase {

    // MARK: - The shared table

    private struct Case {
        let name: String
        let operations: String
        let expectedOrder: String
    }

    /// SHA-256 of the table. A change to the table must be the same change in both repositories.
    private static let tableSha256 = "07a3ccb01b0c33054c6ecf37609b6ccf8deb5410dbfa0274f474255f6915bbd3"

    private static let columns = ["name", "operations", "expected_order", "description"]

    private func tableData() throws -> Data {
        let url = try XCTUnwrap(
            Bundle.module.url(forResource: "call-key-priority-cases", withExtension: "tsv"),
            "call-key-priority-cases.tsv is missing from the test bundle")
        return try Data(contentsOf: url)
    }

    /// The rows of the table. Lines end with LF or CRLF (`isNewline` is true for both).
    private func parseCases(_ data: Data) throws -> [Case] {
        let text = try XCTUnwrap(String(data: data, encoding: .utf8), "the table is not UTF-8")
        var rows: [[String]] = []
        for rawLine in text.split(whereSeparator: \.isNewline) {
            let line = String(rawLine)
            if line.isEmpty || line.hasPrefix("#") { continue }
            rows.append(line.components(separatedBy: "\t"))
        }
        let header = try XCTUnwrap(rows.first, "the table has no header")
        XCTAssertEqual(header, Self.columns, "the columns of the table changed")
        var cases: [Case] = []
        for row in rows.dropFirst() {
            XCTAssertEqual(row.count, Self.columns.count, "a row of the table has the wrong number of columns: \(row)")
            guard row.count == Self.columns.count else { continue }
            cases.append(Case(name: row[0], operations: row[1], expectedOrder: row[2]))
        }
        return cases
    }

    private func group(of name: String) throws -> CallKeyPriority.Group {
        switch name.first {
        case "H": return .hwOnly
        case "K": return .kms
        case "O": return .other
        default:
            XCTFail("a key name must start with H, K or O: \(name)")
            return .other
        }
    }

    func testTheTableIsTheSharedOne() throws {
        let digest = SHA256.hash(data: try tableData()).map { String(format: "%02x", $0) }.joined()
        XCTAssertEqual(digest, Self.tableSha256, "call-key-priority-cases.tsv is not the shared table")
    }

    func testEveryRowOfTheTableGivesItsExpectedOrder() throws {
        let cases = try parseCases(try tableData())
        XCTAssertGreaterThanOrEqual(cases.count, 21, "the table lost rows")
        for testCase in cases {
            var list = CallKeyPriority()
            for operation in testCase.operations.split(separator: " ") {
                let kind = operation.first
                let key = String(operation.dropFirst())
                switch kind {
                case "+": list.add(id: key, group: try group(of: key))
                case "-": list.remove(key)
                case "^": list.moveUp(key)
                case "v": list.moveDown(key)
                case "=":
                    // Section 4a: a confirmed pairing with the same device by the same method is stored under
                    // the name the earlier key has, so the list meets a key it already holds. That key keeps its
                    // place and its mark.
                    XCTAssertTrue(list.contains(key), "\(testCase.name): \(operation) replaces a key that is not held")
                    let before = list
                    list.add(id: key, group: try group(of: key))
                    XCTAssertEqual(list, before, "\(testCase.name): \(operation) moved the key or changed its mark")
                default: XCTFail("\(testCase.name): unknown operation \(operation)")
                }
            }
            XCTAssertEqual(list.ids.joined(separator: " "), testCase.expectedOrder,
                           "\(testCase.name): \(testCase.operations)")
        }
    }

    /// The app never replays operations: it keeps the order and the marks, and after each key arrives or leaves it
    /// rebuilds the list from the keys the vault holds (`CallKeyPriority.reconciled`). That path must give the table's
    /// result too, with every key arriving at a later time than the one before.
    func testEveryRowOfTheTableGivesItsExpectedOrderWhenTheListIsRebuiltFromTheVault() throws {
        let cases = try parseCases(try tableData())
        for testCase in cases {
            var held: [CallKeyPriority.Candidate] = []
            var stored: CallKeyPriority.Stored?
            var list = CallKeyPriority()
            var step = 0
            for operation in testCase.operations.split(separator: " ") {
                step += 1
                let kind = operation.first
                let key = String(operation.dropFirst())
                switch kind {
                case "+":
                    held.append(CallKeyPriority.Candidate(
                        id: key, group: try group(of: key), createdAt: Date(timeIntervalSince1970: Double(step))))
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                case "-":
                    held.removeAll(where: { $0.id == key })
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                case "^":
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                    list.moveUp(key)
                case "v":
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                    list.moveDown(key)
                case "=":
                    // The vault entry is updated in place: same name, new material, and a date later than every
                    // key before it.
                    let index = try XCTUnwrap(held.firstIndex(where: { $0.id == key }),
                                              "\(testCase.name): \(operation) replaces a key that is not held")
                    held[index] = CallKeyPriority.Candidate(
                        id: key, group: held[index].group, createdAt: Date(timeIntervalSince1970: Double(step)))
                    list = CallKeyPriority.reconciled(stored: stored, candidates: held)
                default:
                    XCTFail("\(testCase.name): unknown operation \(operation)")
                }
                // What is stored survives a restart: the next step starts from the decoded form.
                let data = try XCTUnwrap(list.stored.encoded(), "\(testCase.name): the list does not encode")
                stored = try XCTUnwrap(CallKeyPriority.Stored.decode(data), "\(testCase.name): the list does not decode")
            }
            XCTAssertEqual(list.ids.joined(separator: " "), testCase.expectedOrder,
                           "\(testCase.name) (rebuilt from the vault): \(testCase.operations)")
        }
    }

    // MARK: - Groups

    func testGroupsFollowTheOriginAndTheClass() {
        XCTAssertEqual(CallKeyPriority.group(origin: .kms, keyClass: .hwOnly), .hwOnly)
        XCTAssertEqual(CallKeyPriority.group(origin: .manual, keyClass: .hwOnly), .hwOnly)
        XCTAssertEqual(CallKeyPriority.group(origin: .kms, keyClass: .shared), .kms)
        XCTAssertEqual(CallKeyPriority.group(origin: .kms, keyClass: .swOnly), .kms)
        XCTAssertEqual(CallKeyPriority.group(origin: .nfc, keyClass: .shared), .other)
        XCTAssertEqual(CallKeyPriority.group(origin: .proximity, keyClass: .shared), .other)
        XCTAssertEqual(CallKeyPriority.group(origin: .manual, keyClass: .shared), .other)
    }

    // MARK: - First run (section 5)

    func testFirstRunOrdersHwOnlyThenKmsThenOthersAndDoesNotDependOnTheInputOrder() {
        func candidate(_ id: String, _ group: CallKeyPriority.Group, _ seconds: Double?) -> CallKeyPriority.Candidate {
            CallKeyPriority.Candidate(id: id, group: group, createdAt: seconds.map { Date(timeIntervalSince1970: $0) })
        }
        let candidates = [
            candidate("O1", .other, 30),
            candidate("K2", .kms, 90),
            candidate("H1", .hwOnly, 10),
            candidate("O3", .other, nil),
            candidate("K1", .kms, 20),
            candidate("H2", .hwOnly, 50),
            candidate("O2", .other, 10),
        ]
        // H and K newest first, O oldest first, a key with no date after the dated ones of its group.
        let expected = ["H2", "H1", "K2", "K1", "O2", "O1", "O3"]
        XCTAssertEqual(CallKeyPriority.firstRun(candidates).ids, expected)
        XCTAssertEqual(CallKeyPriority.firstRun(candidates.reversed()).ids, expected)
        XCTAssertFalse(CallKeyPriority.firstRun(candidates).entries.contains(where: { $0.placedByHand }),
                       "no key starts placed by hand")
        XCTAssertEqual(CallKeyPriority.reconciled(stored: nil, candidates: candidates).ids, expected,
                       "nothing stored: the first run")
    }

    func testFirstRunBreaksTiesByIdAndIgnoresADuplicateId() {
        let t = Date(timeIntervalSince1970: 5)
        let candidates = [
            CallKeyPriority.Candidate(id: "b", group: .kms, createdAt: t),
            CallKeyPriority.Candidate(id: "a", group: .kms, createdAt: t),
            CallKeyPriority.Candidate(id: "a", group: .other, createdAt: t),
        ]
        XCTAssertEqual(CallKeyPriority.firstRun(candidates).ids, ["a", "b"])
    }

    // MARK: - Rebuilding from what is stored

    func testRebuildingDropsADeletedKeyWithItsMarkAndAddsANewKeyByTheRule() {
        let t = { (seconds: Double) in Date(timeIntervalSince1970: seconds) }
        var list = CallKeyPriority()
        list.add(id: "K1", group: .kms)
        list.add(id: "O1", group: .other)
        list.moveUp("O1")
        XCTAssertEqual(list.ids, ["O1", "K1"])
        XCTAssertTrue(list.isPlacedByHand("O1"))

        // K1 is gone from the vault, K2 arrived: O1 stays first (placed), K2 goes below it.
        let held = [
            CallKeyPriority.Candidate(id: "O1", group: .other, createdAt: t(1)),
            CallKeyPriority.Candidate(id: "K2", group: .kms, createdAt: t(9)),
        ]
        let rebuilt = CallKeyPriority.reconciled(stored: list.stored, candidates: held)
        XCTAssertEqual(rebuilt.ids, ["O1", "K2"])
        XCTAssertTrue(rebuilt.isPlacedByHand("O1"))
        XCTAssertFalse(rebuilt.isPlacedByHand("K2"))
    }

    func testRebuildingAddsSeveralNewKeysOldestFirstAsIfTheyArrivedOneByOne() {
        let t = { (seconds: Double) in Date(timeIntervalSince1970: seconds) }
        let stored = CallKeyPriority.Stored(keys: [CallKeyPriority.Stored.Key(id: "K0", placed: false)])
        let held = [
            CallKeyPriority.Candidate(id: "K0", group: .kms, createdAt: t(1)),
            CallKeyPriority.Candidate(id: "K2", group: .kms, createdAt: t(30)),
            CallKeyPriority.Candidate(id: "K1", group: .kms, createdAt: t(20)),
            CallKeyPriority.Candidate(id: "O1", group: .other, createdAt: t(25)),
        ]
        // K1 (20) goes above K0, O1 (25) at the end, K2 (30) above K1.
        XCTAssertEqual(CallKeyPriority.reconciled(stored: stored, candidates: held).ids, ["K2", "K1", "K0", "O1"])
    }

    func testRebuildingWhenNothingStoredSurvivesIsTheFirstRun() {
        let stored = CallKeyPriority.Stored(keys: [CallKeyPriority.Stored.Key(id: "gone", placed: true)])
        let held = [
            CallKeyPriority.Candidate(id: "O1", group: .other, createdAt: Date(timeIntervalSince1970: 1)),
            CallKeyPriority.Candidate(id: "K1", group: .kms, createdAt: Date(timeIntervalSince1970: 2)),
        ]
        let rebuilt = CallKeyPriority.reconciled(stored: stored, candidates: held)
        XCTAssertEqual(rebuilt.ids, ["K1", "O1"])
        XCTAssertFalse(rebuilt.entries.contains(where: { $0.placedByHand }))
    }

    func testAMoveMarksOnlyTheMovedKeyAndAnEdgeMoveMarksToo() {
        var list = CallKeyPriority()
        list.add(id: "K1", group: .kms)
        list.add(id: "O1", group: .other)
        XCTAssertFalse(list.moveUp("K1"), "the first key cannot go up")
        XCTAssertTrue(list.isPlacedByHand("K1"), "an edge move still marks the key")
        XCTAssertFalse(list.isPlacedByHand("O1"))
        XCTAssertFalse(list.moveDown("O1"), "the last key cannot go down")
        XCTAssertTrue(list.isPlacedByHand("O1"))
        XCTAssertFalse(list.moveUp("missing"), "a key that is not in the list does nothing")
        XCTAssertEqual(list.ids, ["K1", "O1"])
    }

    // MARK: - Stored form

    func testTheStoredFormRoundTripsAndRefusesWhatIsNotOfThisVersion() throws {
        var list = CallKeyPriority()
        list.add(id: "K1", group: .kms)
        list.add(id: "O1", group: .other)
        list.moveUp("O1")
        let data = try XCTUnwrap(list.stored.encoded())
        let decoded = try XCTUnwrap(CallKeyPriority.Stored.decode(data))
        XCTAssertEqual(decoded, list.stored)
        XCTAssertEqual(decoded.keys.map { $0.id }, ["O1", "K1"])
        XCTAssertEqual(decoded.keys.map { $0.placed }, [true, false])

        XCTAssertNil(CallKeyPriority.Stored.decode(Data("not json".utf8)))
        XCTAssertNil(CallKeyPriority.Stored.decode(Data()))
        let otherVersion = CallKeyPriority.Stored(version: 99, keys: [])
        XCTAssertNil(CallKeyPriority.Stored.decode(try XCTUnwrap(otherVersion.encoded())))
    }

    // MARK: - The store

    private final class MemoryBacking: CallKeyPriorityBacking {
        var data: Data?
        var unreadable = false
        /// The Keychain refuses the write: nothing is stored and `write` says so.
        var failWrites = false
        private(set) var writes = 0

        func read() -> CallKeyPriorityStoredRead {
            if unreadable { return .unreadable }
            if let data { return .found(data) }
            return .absent
        }

        func write(_ data: Data) -> Bool {
            if failWrites { return false }
            self.data = data
            writes += 1
            return true
        }
    }

    /// The keys "in the vault" of a store test: a store reads them through the same closure the real one reads the
    /// Keychain with.
    private final class Held {
        var items: [CallKeyPriority.Candidate] = []

        func add(_ id: String, _ group: CallKeyPriority.Group, at seconds: Double) {
            items.append(CallKeyPriority.Candidate(id: id, group: group, createdAt: Date(timeIntervalSince1970: seconds)))
        }

        func remove(_ id: String) {
            items.removeAll(where: { $0.id == id })
        }

        /// The vault updates the entry in place (same name, new material): the key stays, with a later date.
        func replace(_ id: String, at seconds: Double) {
            guard let index = items.firstIndex(where: { $0.id == id }) else { return }
            items[index] = CallKeyPriority.Candidate(
                id: id, group: items[index].group, createdAt: Date(timeIntervalSince1970: seconds))
        }
    }

    private func makeStore(_ backing: MemoryBacking, _ held: Held) -> CallKeyPriorityStore {
        CallKeyPriorityStore(backing: backing, candidates: { held.items })
    }

    func testTheStoreWritesTheFirstRunListOnceAndNothingWhenNothingChanged() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        store.syncWithVault()
        XCTAssertEqual(backing.writes, 1)
    }

    func testTheStoreWritesNothingForAnEmptyVault() {
        let backing = MemoryBacking()
        let store = makeStore(backing, Held())
        XCTAssertEqual(store.current().ids, [])
        XCTAssertEqual(backing.writes, 0)
    }

    func testAKeyMovedAboveKmsStaysAboveWhenNewKmsKeysArriveAndAfterARestart() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        var store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])

        XCTAssertEqual(store.moveUp("O1").list.ids, ["O1", "K1"])

        held.add("K2", .kms, at: 3)
        store.syncWithVault()
        XCTAssertEqual(store.current().ids, ["O1", "K2", "K1"])

        // A new store over the same backing is a restart of the app.
        store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["O1", "K2", "K1"])
        held.add("K3", .kms, at: 4)
        XCTAssertEqual(store.current().ids, ["O1", "K3", "K2", "K1"])
    }

    /// Section 4a: a confirmed pairing with the same device by the same method is stored under the name the earlier
    /// key has, and the vault updates that entry in place. The key keeps its place and its mark, with or without a
    /// restart in between and whatever the entry's date becomes.
    func testAKeyStoredAgainUnderTheSameNameKeepsItsPlaceAndMark() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        var store = makeStore(backing, held)
        XCTAssertEqual(store.moveUp("O1").list.ids, ["O1", "K1"])

        held.replace("O1", at: 9)
        store.syncWithVault()
        XCTAssertEqual(store.current().ids, ["O1", "K1"])
        XCTAssertTrue(store.current().isPlacedByHand("O1"))
        XCTAssertFalse(store.current().isPlacedByHand("K1"))

        store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["O1", "K1"])
        XCTAssertTrue(store.current().isPlacedByHand("O1"))

        // The mark still does its work: a new KMS key goes below the key the user put first.
        held.add("K2", .kms, at: 10)
        XCTAssertEqual(store.current().ids, ["O1", "K2", "K1"])
    }

    func testAKeyStoredAgainInItsDefaultPlaceStaysThereAndWritesNothing() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("K1", .kms, at: 1)
        held.add("O1", .other, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        let writes = backing.writes

        held.replace("O1", at: 8)
        store.syncWithVault()
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        XCTAssertFalse(store.current().isPlacedByHand("O1"))
        XCTAssertEqual(backing.writes, writes, "an update in place changes neither the order nor the marks")
    }

    /// Another device of the same person has another identity key, so another name, and so it is a new key (section
    /// 3). So is the same device by the other method: the name starts with the method.
    func testAKeyOfAnotherDeviceOrOfTheOtherMethodIsANewKeyAtTheEnd() {
        let device = Data(repeating: 0x11, count: 32)
        let otherDevice = Data(repeating: 0x22, count: 32)
        let proximity = ProximityPairingStore.vaultEntryName(peerSigningPublicKey: device)
        XCTAssertEqual(ProximityPairingStore.vaultEntryName(peerSigningPublicKey: device), proximity,
                       "the same device by the same method is the same name")
        let otherProximity = ProximityPairingStore.vaultEntryName(peerSigningPublicKey: otherDevice)
        let nfc = "nfc-" + String(proximity.dropFirst("prox-".count))
        XCTAssertEqual(Set([proximity, otherProximity, nfc]).count, 3)

        let backing = MemoryBacking()
        let held = Held()
        held.add("K1", .kms, at: 1)
        held.add(proximity, .other, at: 2)
        let store = makeStore(backing, held)
        _ = store.moveUp(proximity)
        XCTAssertEqual(store.current().ids, [proximity, "K1"])

        held.add(otherProximity, .other, at: 3)
        held.add(nfc, .other, at: 4)
        XCTAssertEqual(store.current().ids, [proximity, "K1", otherProximity, nfc])
        XCTAssertTrue(store.current().isPlacedByHand(proximity))
        XCTAssertFalse(store.current().isPlacedByHand(otherProximity))
        XCTAssertFalse(store.current().isPlacedByHand(nfc))
    }

    func testAKeyDeletedFromTheVaultLeavesTheListAndLosesItsMark() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        _ = store.moveUp("O1")

        held.remove("O1")
        XCTAssertEqual(store.current().ids, ["K1"])
        // The same name again is a new key: not placed, so the new KMS key goes above it.
        held.add("O1", .other, at: 5)
        held.add("K2", .kms, at: 6)
        XCTAssertEqual(store.current().ids, ["K2", "K1", "O1"])
        XCTAssertFalse(store.current().isPlacedByHand("O1"))
    }

    func testAStoredListThatCannotBeReadIsNeverOverwritten() throws {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        _ = store.moveUp("O1")
        let before = try XCTUnwrap(backing.data)
        let writesBefore = backing.writes

        backing.unreadable = true
        held.add("K2", .kms, at: 3)
        // The order shown while the store is unreadable is the first-run one, and nothing is written.
        XCTAssertEqual(store.current().ids, ["K2", "K1", "O1"])
        XCTAssertFalse(store.moveDown("K2").saved)
        XCTAssertEqual(backing.writes, writesBefore)
        XCTAssertEqual(backing.data, before)

        backing.unreadable = false
        XCTAssertEqual(store.current().ids, ["O1", "K2", "K1"])
    }

    /// The arrow press of Key management: when the new order cannot be stored the store says so (the screen shows its
    /// error banner), and the list it returns is the stored one, not the move that was lost.
    func testAMoveThatCannotBeStoredIsReportedAndLeavesTheStoredOrder() throws {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        let stored = try XCTUnwrap(backing.data)

        backing.failWrites = true
        let refused = store.moveUp("O1")
        XCTAssertFalse(refused.saved)
        XCTAssertEqual(refused.list.ids, ["K1", "O1"])
        XCTAssertEqual(backing.data, stored)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        XCTAssertFalse(store.moveDown("K1").saved)

        backing.failWrites = false
        let accepted = store.moveUp("O1")
        XCTAssertTrue(accepted.saved)
        XCTAssertEqual(accepted.list.ids, ["O1", "K1"])
        XCTAssertEqual(store.current().ids, ["O1", "K1"])
    }

    func testAMoveIsReportedAsNotStoredWhenTheStoredListCannotBeRead() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertTrue(store.moveUp("O1").saved)
        let writes = backing.writes

        backing.unreadable = true
        let move = store.moveDown("O1")
        XCTAssertFalse(move.saved)
        XCTAssertEqual(backing.writes, writes)
    }

    func testAMoveThatNeedsNoWriteIsReportedAsStored() {
        let backing = MemoryBacking()
        let held = Held()
        held.add("K1", .kms, at: 1)
        let store = makeStore(backing, held)
        _ = store.moveUp("K1")
        let writes = backing.writes

        // A key that is not in the list changes nothing, so there is nothing to store and nothing is lost.
        backing.failWrites = true
        let move = store.moveUp("missing")
        XCTAssertTrue(move.saved)
        XCTAssertEqual(move.list.ids, ["K1"])
        XCTAssertEqual(backing.writes, writes)
    }

    func testAStoredListThatIsDamagedIsRebuiltAsTheFirstRun() {
        let backing = MemoryBacking()
        backing.data = Data("damaged".utf8)
        let held = Held()
        held.add("O1", .other, at: 1)
        held.add("K1", .kms, at: 2)
        let store = makeStore(backing, held)
        XCTAssertEqual(store.current().ids, ["K1", "O1"])
        XCTAssertEqual(backing.writes, 1)
        XCTAssertNotNil(backing.data.flatMap { CallKeyPriority.Stored.decode($0) })
    }

    // MARK: - Display and the cleanup of the removed entries

    func testShortFingerprintIsTheFirst64BitsInFourGroups() {
        let full = "0123456789abcdef" + String(repeating: "0", count: 48)
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: full), "0123.4567.89ab.cdef")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: full.uppercased()), "0123.4567.89ab.cdef")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: "d00d.d00d.d00d.d00d"), "d00d.d00d.d00d.d00d")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: nil), "—")
        XCTAssertEqual(CallKeyPriorityStore.shortFingerprint(label: ""), "—")
    }

    func testOnlyTheRotatedEphemeralEntriesOfTheRemovedKeyRotationAreCleanedUp() {
        let names = [
            "peer.4fd0c1d8-0000-0000-0000-000000000001",
            "rotated_ephemeral.1784800000",
            "peer.alice",
            "nfc-0123456789abcdef",
            "prox-0123456789abcdef",
            "11111111-1111-1111-1111-111111111111",
            "__device.x25519.priv",
            "__callkeyprio.v1",
        ]
        let removed = LegacyIdentityKeyEntries.namesToRemove(from: names, origin: { name in
            // "peer.alice" was stored with an explicit manual origin: it is a key someone typed, not an identity entry.
            name == "peer.alice" ? .manual : PskOrigin.inferred(fromAccountName: name)
        })
        // The public keys of scanned contacts stay: they are no call keys and are not part of this cleanup.
        XCTAssertEqual(removed, ["rotated_ephemeral.1784800000"])
    }

    func testTheOrderEntryIsDeviceInternalSoItIsNeverACallKeyOrAdvertised() {
        XCTAssertEqual(PskOrigin.inferred(fromAccountName: VaultCallKeyPriorityBacking.accountName), .deviceInternal)
        XCTAssertFalse(PskAdvertising.isEligibleMatchCandidate(origin: .deviceInternal))
    }

    // MARK: - Protection of the order entry

    /// The order is metadata, not a secret: it is read on the main thread and while a call is being set up, so it
    /// must never carry the user-presence access control the keys take when biometric key protection is on.
    func testTheOrderEntryIsPinnedToAClassWithNoAccessControlAndTheKeysAreNot() {
        typealias Protection = SovereignKeyVault.EntryProtection
        XCTAssertEqual(Protection.forAccount(VaultCallKeyPriorityBacking.accountName), .deviceMetadata)
        XCTAssertEqual(Protection.deviceMetadata.pinnedAccessClass, .afterFirstUnlockThisDeviceOnly)
        XCTAssertNil(Protection.followsKeyPolicy.pinnedAccessClass)
        for name in [
            "11111111-1111-1111-1111-111111111111",
            "nfc-0123456789abcdef",
            "prox-0123456789abcdef",
            "__device.x25519.priv",
            "__kmsname.abcdef",
            "__kms.active_epoch.3",
        ] {
            XCTAssertEqual(Protection.forAccount(name), .followsKeyPolicy, name)
        }
    }

    #if canImport(Security)
    /// The attributes a write and a re-protection give the entry. The plain object below stands in for the
    /// `SecAccessControl` a key takes when biometric protection is on: the order must come out without it, a key
    /// with it.
    func testTheOrderEntryIsWrittenAfterFirstUnlockWithoutAnAccessControlEvenWhenKeysTakeOne() {
        let accessControl = NSObject()
        let afterFirstUnlock = kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly as String

        for given in [accessControl, nil] as [NSObject?] {
            let order = SovereignKeyVault.protectionAttributes(
                forAccount: VaultCallKeyPriorityBacking.accountName, accessControl: given)
            XCTAssertNil(order[kSecAttrAccessControl as String])
            XCTAssertEqual(order[kSecAttrAccessible as String] as? String, afterFirstUnlock)
            XCTAssertEqual(order.count, 1)
        }

        let protectedKey = SovereignKeyVault.protectionAttributes(
            forAccount: "nfc-0123456789abcdef", accessControl: accessControl)
        XCTAssertNotNil(protectedKey[kSecAttrAccessControl as String])
        XCTAssertNil(protectedKey[kSecAttrAccessible as String])

        let plainKey = SovereignKeyVault.protectionAttributes(forAccount: "nfc-0123456789abcdef", accessControl: nil)
        XCTAssertNil(plainKey[kSecAttrAccessControl as String])
        let plainClass = KeychainAccessibilityPolicy.secAttrAccessible(for: .sessionPsk) as String
        XCTAssertEqual(plainKey[kSecAttrAccessible as String] as? String, plainClass)
    }
    #endif

    // MARK: - No notification inside the lock

    /// `CallKeyPriorityStore` writes the order while it holds its lock, on the thread that asked, the main thread
    /// included. A vault notification posted from there would run the block observers inside the critical section,
    /// and an observer registered on another queue makes the poster wait for that queue. The write of the order
    /// therefore must not be announced. (The Keychain test in `SovereignKeyVaultNotificationTests` runs the real
    /// write; this one pins the rule the vault applies, without a Keychain.)
    func testTheWriteOfTheOrderIsNotAnnouncedOnTheVaultNotification() {
        XCTAssertFalse(SovereignKeyVault.announcesChange(ofAccount: VaultCallKeyPriorityBacking.accountName))
    }

    func testOnlyTheKeysAUserCanSeeAreAnnounced() {
        XCTAssertTrue(SovereignKeyVault.announcesChange(ofAccount: "11111111-1111-1111-1111-111111111111"))
        XCTAssertTrue(SovereignKeyVault.announcesChange(ofAccount: "nfc-0123456789abcdef"))
        XCTAssertTrue(SovereignKeyVault.announcesChange(ofAccount: "prox-0123456789abcdef"))
        XCTAssertFalse(SovereignKeyVault.announcesChange(ofAccount: "__device.x25519.priv"))
        XCTAssertFalse(SovereignKeyVault.announcesChange(ofAccount: "__kmsname.abcdef"))
    }
}
